CREATE COLUMN TABLE "TEST_AP"."OPCI" ("InstancePk" INTEGER CS_INT NOT NULL , "TemplateFk" INTEGER CS_INT, "InstName" NVARCHAR(100), "InstDesc" NVARCHAR(100), "Creator" NVARCHAR(100), "Status" NVARCHAR(1) DEFAULT 'N', "StartDate" LONGDATE CS_LONGDATE, "CloseDate" LONGDATE CS_LONGDATE, "CloPrcnt" DECIMAL(21,6) CS_FIXED, "Memo" NCLOB MEMORY THRESHOLD 1000, "Attachment" NCLOB MEMORY THRESHOLD 1000, "AtcEntry" INTEGER CS_INT, PRIMARY KEY ("InstancePk")) UNLOAD PRIORITY 5  AUTO MERGE 